import SwiftUI
import AtiCleanerCore

@MainActor final class DupVM:ObservableObject{@Published var groups:[DuplicateGroup]=[];@Published var scanning=false;@Published var minSize:Int64=5*1024*1024;@Published var root=FileManager.default.homeDirectoryForCurrentUser.path
func scan(){guard !scanning else{return};scanning=true;Task{let r=root;let m=minSize;let found=await Task.detached{DuplicateScanner().scan(root:URL(fileURLWithPath:r),minSize:m,progress:{_ in},isCancelled:{false})}.value;groups=found;scanning=false}}}
struct DuplicatesView:View{@StateObject private var vm=DupVM();var body:some View{VStack(alignment:.leading,spacing:16){PageHeader(icon:"doc.on.doc",title:"Çift Dosyalar",subtitle:"Dosya adı farklı olsa bile aynı içeriği SHA-256 ile doğrulayın.",tint:Theme.duplicates,actionTitle:"Tara",action:vm.scan);HStack{Picker("Minimum Dosya Boyutu",selection:$vm.minSize){ForEach([1,5,10,50,100],id:\.self){n in Text("\(n) MB").tag(Int64(n*1024*1024))}};Picker("Tarama Konumu",selection:$vm.root){Text("Ev Dizini").tag(FileManager.default.homeDirectoryForCurrentUser.path);Text("Belgeler").tag(FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Documents").path);Text("İndirilenler").tag(FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Downloads").path);Text("Masaüstü").tag(FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Desktop").path);Text("Fotoğraflar").tag(FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Pictures").path)}}.padding(12).background(RoundedRectangle(cornerRadius:12).fill(Color(nsColor:.controlBackgroundColor)));if vm.scanning{ProgressView("Dosya içerikleri karşılaştırılıyor…")}else if vm.groups.isEmpty{VStack(spacing:18){ReadyRing(icon:"doc.on.doc.fill",title:"Taramaya Hazır",detail:vm.minSize.formattedBytes+"+",tint:Theme.duplicates);HStack{InfoTile(icon:"photo.fill",title:"Fotoğraflar",subtitle:"Aynı görseller",tint:Theme.duplicates);InfoTile(icon:"film.fill",title:"Videolar",subtitle:"Aynı videolar",tint:Theme.duplicates);InfoTile(icon:"doc.text.fill",title:"Belgeler",subtitle:"Aynı belgeler",tint:Theme.duplicates);InfoTile(icon:"checkmark.shield.fill",title:"SHA-256",subtitle:"İçerik doğrulama",tint:Theme.duplicates)}.frame(maxWidth:840)}.frame(maxWidth:.infinity)}else{List(vm.groups){g in Section("\(g.files.count) kopya • İsraf \(g.wasteSize.formattedBytes)"){ForEach(g.files){f in HStack{Text(URL(fileURLWithPath:f.path).lastPathComponent);Spacer();Text(f.size.formattedBytes).foregroundStyle(.secondary)}}}}}}.padding(24)}}
